{
  "missing_information": [
    {
      "category": "Trigger & Timing",
      "gap": "It is unclear when exactly the scheduling process starts each week and what event or deadline initiates it.",
      "why_it_matters": "Without knowing the trigger and timing, it is impossible to model the process start event or set up automated reminders and deadlines."
    },
    {
      "category": "Participants & Roles",
      "gap": "The specific family members involved and their roles (e.g., primary caregiver, backup caregiver) are not defined.",
      "why_it_matters": "Role clarity is needed to assign tasks correctly in a workflow model and to determine who receives which notifications or requests."
    },
    {
      "category": "Schedule Creation Method",
      "gap": "The mechanism used to draft and share the initial schedule (e.g., verbal discussion, shared calendar, messaging app, spreadsheet) is not described.",
      "why_it_matters": "The tool or channel used determines where automation can be applied and what data sources or integrations are relevant."
    },
    {
      "category": "Conflict & Exception Handling",
      "gap": "The steps taken when someone cannot fulfill their slot are not specified beyond 'find another arrangement,' leaving the resolution subprocess undefined.",
      "why_it_matters": "Exception paths are critical for complete process modeling and are often the highest-value targets for automation or decision-support."
    },
    {
      "category": "Communication & Confirmation",
      "gap": "How family members confirm their availability or acceptance of the schedule (and any changes) is not described.",
      "why_it_matters": "Without a defined confirmation step, it is unclear whether the process has a formal closure point or how agreement is recorded."
    },
    {
      "category": "Decision Criteria",
      "gap": "The criteria used to decide who takes over a slot when someone is unavailable are not stated.",
      "why_it_matters": "Explicit decision rules are required to model branching logic and to assess whether automated matching or suggestion of alternatives is feasible."
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "On which day and at what point in the week does the scheduling process typically begin, and is it started by a specific person or a shared prompt?",
      "targets": ["Trigger & Timing"]
    },
    {
      "id": "Q2",
      "question": "Which family members are regularly involved in the caregiving schedule, and do any of them have a defined primary or backup role?",
      "targets": ["Participants & Roles"]
    },
    {
      "id": "Q3",
      "question": "What tool or channel do you currently use to draft and share the weekly schedule with the rest of the family?",
      "targets": ["Schedule Creation Method"]
    },
    {
      "id": "Q4",
      "question": "When someone says they cannot make their slot, what are the specific steps that follow to find a replacement arrangement?",
      "targets": ["Conflict & Exception Handling"]
    },
    {
      "id": "Q5",
      "question": "How does each family member confirm that they have seen and accepted their assigned slots, and is that confirmation recorded anywhere?",
      "targets": ["Communication & Confirmation"]
    },
    {
      "id": "Q6",
      "question": "When choosing who covers an unavailable person's slot, what factors or rules guide that decision (e.g., proximity, prior commitments, rotation order)?",
      "targets": ["Decision Criteria"]
    }
  ]
}
